INSERT INTO Procedure (Name, Step, HumiditySetpoint, TemperatureSetpointC, SoakTime, Accuracy, Adjustment, Description) VALUES ('Advanced Temperature Adjustment', 'AdvancedTempStart', NULL, NULL, '', NULL, 0, 'Minimum of four temperature points required, with one as close to 0°C as reasonably achievable are required for this. This test collects all set points and generates new PT100 coefficients specific to the probe being tested.\\nMore test points will improve accuracy to some extent, but they should be evenly distrubuted to avoid biasing the temperature curve.');
