INSERT INTO Procedure (Name, Step, HumiditySetpoint, TemperatureSetpointC, SoakTime, Accuracy, Adjustment, Description) VALUES ('Full Calibration with Advanced Temperature Adjustment', 'As-FoundStart', NULL, NULL, '', NULL, 0, 'A full calibration, including custom coefficients for the PT100 probe.\\nFirst collects as-found data. Runs adjustment for temperature, saves coefficients, then runs adjustment for Humidity.\\nFinally collects as-left data. This procedure is likely to take several hours. 0 setpoints for temperature may have to be tweaked based on capabilities of the chamber.\\nImportant: Temperature should be adjusted before humidity. These should not be done in one step, as this will affect the humidity accuracy.');
