INSERT INTO Procedure (Name, Step, HumiditySetpoint, TemperatureSetpointC, SoakTime, Accuracy, Adjustment, Description) VALUES ('Full Calibration with single temperature adjustment', 'As-FoundStart', NULL, NULL, '', NULL, 0, 'Full calibration with adjustment. Only a single point adjustment is performed for temperature here. This is best if the temperature is expected to remain consistently close to a single set point. The adjust step command saves the test points to the probe. Temperature adjust point is done first and adjustment step done to prevent issues with temperature accuracy affecting humidity.');
